traps.trap02.txt:
// 石桌前的trap

	PlayerGoto(5, 17);
	SetPlayerDir(5);
	Say("独孤剑：咦？这桌子上有一封信。", 8);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 5, 19); 
	SetNpcDir("张琳心", 5);
	Say("张琳心：哦？看看上面写的什么？", 21);
	Say("独孤剑：是一首诗。", 1);
	Say("<color=Red>西山东月起晚钟，云盘峰顶雾朝松。<enter>指点英雄一二事，乾坤倒转半枰中。<color=Black>");
	Say("张琳心：这是什么意思？", 21);
	Say("独孤剑：我也猜不透。", 1);
	Say("张琳心：先把信收好，留着以后再慢慢琢磨。", 21);
	Say("独孤剑：也好。", 1);
	
	SetNpcActionFile("独孤剑", 0, "mpc009_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc009_2.asf");
	NpcSpecialAction("独孤剑", "mpc009_1.asf");    // 独孤剑伸出手
	Sleep(1000);
	
	PlaySound("特_捡到特殊物品.wav");
	DelObj("武夷密洞书信");
	AddObj("变成灰的信.ini", 6, 16, 0);
	Sleep(500);
	DelObj("变成灰的信");
	SaveObj();
	
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc009_3.asf");    // 独孤剑缩回伸出的手
	Sleep(1500);
	
	Say("张琳心：哎呀，糟糕！怎么变成飞灰了？", 25);
	Say("独孤剑：恐怕是时间太久了，不知诗中藏有什么玄机。", 1);
	Say("张琳心：把它记在心里吧，说不定日后遇到高人就能解开这谜。", 21);
	Say("独孤剑：我们再四处看看。", 1);
	SetNpcKind("张琳心", 3);

	SetMapTrap(2,"");
	Return;

traps.trap03.txt:
// 墙壁前的trap

	SetNpcKind("张琳心", 1);
	PlayerGoto(4, 14);
	SetPlayerDir(4);
	Say("独孤剑：咦，墙上有字。", 8);
	NpcGoto("张琳心", 4, 15);
	SetNpcDir("张琳心", 4);
	Say("海某一世英雄，不慎为武夷无耻之徒柳四海所暗算，困在迷宫中，此处机关四伏，不得出口，吾自知难逃一死，故在此留下本人最得意之武功“风雷九洲”之剑法，好叫后辈知我海某的手段。");
	Say("独孤剑：看来这海某人一定是五色教的前任教主海山阳，三十年前他离奇失踪，随后五色教也作鸟兽四散，原来他是丧生在此。", 1);
	Say("张琳心：听说当年他的剑法天下无敌。", 21);
	Say("独孤剑：不错，可是就算是天下无敌的武功，如果多行不义，也只能落得如此下场。", 1);
	Say("张琳心：……", 24);
	SetNpcDir("张琳心", 3);
	SetPlayerDir(7);
	Say("张琳心：独孤大哥，不如你把这套剑法学下来。", 21);
	Say("独孤剑：这种恶人的武功，不学也罢。", 1);
	Say("张琳心：人会作恶，但武功本是不分善恶的。好人学了以后何尝不能用来除恶扬善。独孤大哥，你日后艰险重重，学了这套武功不是能助你早日了却心愿吗？", 21);
	Say("独孤剑：也好。", 1);
	
	FadeOut();
	AddMagic("magic009_风雷九洲.ini");  // 独孤剑学会风雷九州
	SetMagicLevel("magic009_风雷九洲.ini", 2);
	FullLife();
	FullThew();
	FullThew();
	SetPlayerPos(4, 16);
	SetPlayerDir(3);
	SetNpcPos("张琳心", 3, 15);
	SetNpcDir("张琳心", 7);	
	FadeIn();
	
	NpcGoto("张琳心", 5, 13);
	SetNpcDir("张琳心", 5);
	Say("张琳心：这边也有字。", 21);
	PlayerGoto(5, 14);
	SetPlayerDir(5);
	Say("此次吾集血旗门下精英和五色教众在此决战，无奈血旗门近年与金人大战数次，元气大伤，不敌五色教人多势众，吾不得已诱海山阳等入此洞中，正是欲以洞中机关将其困杀。今日看到海山阳已死，四海虽死而无憾，留下本派祖师柳无霜女侠所创之最高武功“凤舞九天”之剑诀为有缘女子。此诀只宜女子修练，可惜吾身为须眉，无法以此剑法的威力和海山阳决战，惜哉。");
	SetNpcDir("张琳心", 1);
	Say("张琳心：柳四海是不是柳中原前辈的父亲？", 21);
	Say("独孤剑：正是，听先师说，当年国家正当危难之际，柳老英雄毅然组织起“血旗门”，团结江湖中人共同抗击金国的侵略，深得我们后辈敬仰。三十年前他和五色教主海山阳一同失踪，原来是和对方在此同归于尽了，唉！", 1);
	Say("独孤剑：张姑娘，不如你将这套“凤舞九天”学下来，如何？", 2);
	Say("张琳心：好啊，日后可以助独孤大哥……不知道我学不学得了前辈的武功。", 95);
	
	FadeOut();
	SetNpcKind("张琳心", 3);
	AddOneMagic("张琳心", "magic021_凤舞九天.ini"); 
	//SetMagicLevel("magic021_凤舞九天.ini", 2);
	SetNpcKind("张琳心", 1);
	SetPlayerPos(4, 19);
	SetPlayerDir(7);
	SetNpcPos("张琳心", 5, 20);
	SetNpcDir("张琳心", 3);	
	FadeIn();
	
	If ($Event <= 230) @Event230;
	
	Say("独孤剑：想不到我们竟有这番奇遇，能够学到两位前辈的绝世武功，可算幸运！", 2);
	Say("张琳心：是啊，不过这洞里阴森森的，我们还是走吧。", 21); 
	Say("独孤剑：好。", 1);
	Goto @Final;
	
@Event230:
	Say("张琳心：独孤大哥，想不到我们竟有这番奇遇，能够学到两位前辈的绝世武功，可算幸运！", 21);
	Say("独孤剑：是啊，只是不知柳中原前辈怎样了，我们还是赶紧去找他吧。", 1);
	Goto @Final;
	
@Final:	 
	SetNpcKind("张琳心", 3);
	SetMapTrap(3,"");
	Memo("在密洞里发现机关。进入一个内洞，发现了当年“血旗门”门主柳四海和“五色教”教主海山阳在此洞中决战，最后同归于尽的秘密。独孤剑和张琳心各自学会了刻在墙壁上的神功“风雷九洲”和“凤舞九天”。");
	Return;
